using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;
using Microsoft.Agents.AI.ChatCompletion;
using System.ComponentModel;

var builder = Host.CreateApplicationBuilder(args);

var apiKey = builder.Configuration["AI:ApiKey"]
    ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set AI:ApiKey in configuration or OPENAI_API_KEY environment variable.");

builder.Services.AddChatClient(b => b
    .UseOpenAIChatClient("gpt-4o-mini-2024-07-18", apiKey));

builder.Services.AddSingleton<ResearchNotes>();
builder.Services.AddSingleton<ResearchTools>();

var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();
var notes = host.Services.GetRequiredService<ResearchNotes>();
var tools = host.Services.GetRequiredService<ResearchTools>();

var agent = new ChatClientAgent(chatClient,
    "ResearchAgent",
    "You are a research assistant. Use the web_search tool to find information about topics, " +
    "and the take_note tool to record key findings. After researching, use summarize_notes to " +
    "produce a final summary. Always search multiple aspects of the topic before summarizing.");

agent.Tools.Add(AIFunctionFactory.Create(tools.WebSearch));
agent.Tools.Add(AIFunctionFactory.Create(tools.TakeNote));
agent.Tools.Add(AIFunctionFactory.Create(tools.SummarizeNotes));

Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

var history = new List<ChatMessage>
{
    new(ChatRole.User,
        $"Research the following topic thoroughly, take notes on key findings, " +
        $"then provide a final summary: {topic}")
};

var options = new AgentInvokeOptions
{
    MaximumIterations = 10,
};

await foreach (var message in agent.InvokeStreamingAsync(history, options))
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
    {
        Console.Write(message.Text);
    }
}

Console.WriteLine("\n\n--- Research Notes ---");
foreach (var note in notes.GetAll())
{
    Console.WriteLine($"• {note}");
}

/// <summary>Stores research notes collected by the agent.</summary>
public sealed class ResearchNotes
{
    private readonly List<string> _notes = [];

    public void Add(string note) => _notes.Add(note);
    public IReadOnlyList<string> GetAll() => _notes.AsReadOnly();
}

/// <summary>Tools available to the research agent.</summary>
public sealed class ResearchTools(ResearchNotes notes)
{
    [Description("Search the web for information on a query. Returns relevant search results.")]
    public string WebSearch([Description("The search query")] string query)
    {
        // Simulated web search - replace with a real search API (Bing, Google, etc.)
        Console.WriteLine($"  [🔍 Searching: \"{query}\"]");
        return $"Search results for '{query}':\n" +
               $"1. Wikipedia article on {query} - provides overview and history.\n" +
               $"2. Recent news: Latest developments in {query} (2026).\n" +
               $"3. Academic paper: Analysis of {query} - key findings and conclusions.\n" +
               "(Replace this stub with a real search API like Bing Search or Google Custom Search)";
    }

    [Description("Take a note to record an important finding during research.")]
    public string TakeNote(
        [Description("The note content to record")] string content)
    {
        notes.Add(content);
        Console.WriteLine($"  [📝 Note taken: \"{content[..Math.Min(content.Length, 60)]}...\"]");
        return $"Note recorded: {content}";
    }

    [Description("Summarize all notes taken so far into a coherent research summary.")]
    public string SummarizeNotes()
    {
        var allNotes = notes.GetAll();
        if (allNotes.Count == 0)
            return "No notes have been taken yet. Use web_search and take_note first.";

        Console.WriteLine($"  [📋 Summarizing {allNotes.Count} notes]");
        return $"Notes to summarize ({allNotes.Count} total):\n" +
               string.Join("\n", allNotes.Select((n, i) => $"{i + 1}. {n}"));
    }
}

